--
-- Class CashMovement as table cash_movements
--
CREATE TABLE "cash_movements" (
    "id" BLOB PRIMARY KEY DEFAULT (unhex(printf('%012x', CAST(unixepoch('now', 'subsecond') * 1000 AS INTEGER)) || '7' || substr(hex(randomblob(2)), 2, 3) || substr('89AB', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(8)), 2, 15))),
    "tenant_id" BLOB NOT NULL,
    "outlet_id" BLOB NOT NULL,
    "cash_session_id" BLOB NOT NULL,
    "direction" TEXT NOT NULL,
    "amount" INTEGER NOT NULL,
    "note" TEXT NOT NULL,
    "source" TEXT NOT NULL DEFAULT ('manual'),
    "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsecond') * 1000 AS INTEGER)),
    "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsecond') * 1000 AS INTEGER)),
    "deleted_at" INTEGER,
    "created_by" BLOB,
    "updated_by" BLOB,
    "version" INTEGER NOT NULL DEFAULT (1),
    "hlc" TEXT NOT NULL,
    "origin_device_id" BLOB,
    CONSTRAINT "cash_movements_fk_0" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "cash_movements_fk_1" FOREIGN KEY ("outlet_id") REFERENCES "outlets" ("id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "cash_movements_fk_2" FOREIGN KEY ("cash_session_id") REFERENCES "cash_sessions" ("id") ON DELETE RESTRICT ON UPDATE NO ACTION
) STRICT;

-- Indexes
CREATE INDEX "cash_movements_session_idx" ON "cash_movements" ("cash_session_id");


--
-- Class CashSession as table cash_sessions
--
